package com.healthcare.portal.dto; import com.healthcare.portal.entity.User; public record UserSummary(Long id,String email,String fullName,String phone,String role,boolean active,boolean emailVerified,boolean forcePasswordChange){public static UserSummary from(User u){return new UserSummary(u.getId(),u.getEmail(),u.getFullName(),u.getPhone(),u.getRole().name(),u.isActive(),u.isEmailVerified(),u.isForcePasswordChange());}}
